SetColumns(0);SetNthreads(1);SetQuitOnError(true);Alarm(120);tt:=Cputime();root:="work/deg10/continuation_20261031b/M3N18/";a:=eval Read(root cat"endomorphism_gluing/global_point13900_absolute.m");PQ<X>:=PolynomialRing(Rationals());function Rat(x)return Rationals()!x[1]/x[2];end function;pabs:=PQ![Rat(x):x in a[2]];assert Degree(pabs)eq 10 and IsIrreducible(pabs);L<theta>:=NumberField(pabs);
function NL(x)return &+[L!Rat(x[i])*theta^(i-1):i in[1..#x]];end function;
zeta:=NL(a[3]);assert zeta^2+zeta+1 eq 0;q,t:=Explode([NL(x):x in a[4]]);E:=EllipticCurve([NL(x):x in a[5]]);assert aInvariants(E)eq[q*t-q+t+2,L!0,q*t^2-q*t+t,L!0,L!0];P:=E![NL(x):x in a[6]];Q:=E![NL(x):x in a[7]];assert P eq E![0,0]and Q eq E![-t,t^2];assert 3*P eq E!0 and P ne E!0 and 18*Q eq E!0 and 9*Q ne E!0 and 6*Q ne E!0;assert P ne 6*Q and P ne -6*Q;assert WeilPairing(P,6*Q,3)ne 1;assert NL(a[8])eq jInvariant(E);
k:=GF(7);PK:=PolynomialRing(k);f7:=PK!pabs;assert IsSquarefree(f7);fac:=Factorization(f7);assert Sort([Degree(v[1]):v in fac])eq[2,2,3,3];out:=[* *];
for ff in fac do if Degree(ff[1])ne 2 then continue;end if;K<r>:=ext<k|ff[1]>;function Red(x)return &+[K!Rat(x[i])*r^(i-1):i in[1..#x]];end function;ER:=EllipticCurve([Red(x):x in a[5]]);PP:=ER![Red(x):x in a[6]];QQ:=ER![Red(x):x in a[7]];assert 3*PP eq ER!0 and PP ne ER!0 and 18*QQ eq ER!0 and 9*QQ ne ER!0 and 6*QQ ne ER!0 and WeilPairing(PP,6*QQ,3)ne 1;assert #ER eq 54;
T:=9*QQ;ER2,phi:=IsogenyFromKernel(ER,PolynomialRing(K).1-T[1]);xd:=-aInvariants(ER)[2]-aInvariants(ER)[1]^2/4-2*T[1];ar:=aInvariants(ER2);Td:=ER2![xd,-(ar[1]*xd+ar[3])/2];P2:=phi(PP);Q2:=2*phi(QQ)+Td;assert 3*P2 eq ER2!0 and P2 ne ER2!0 and 18*Q2 eq ER2!0 and 9*Q2 ne ER2!0 and 6*Q2 ne ER2!0 and WeilPairing(P2,6*Q2,3)ne 1;assert #ER2 eq 54;Append(~out,[* [Integers()!c:c in Coefficients(ff[1])],54,54*]);end for;
Write(root cat"parent_nf_reductions.m",Sprint(out):Overwrite:=true);print "D31B_M318_PARENT_NF_REDUCTIONS_COMPLETE",Degree(pabs),#out,[54,54],Cputime(tt);quit;
